import random

def cognitive_diagnose(symptoms_text):
    # Simulating NLP extraction and probabilistic reasoning
    knowledge_base = {
        "fever": [("Viral Flu", 0.75), ("Malaria", 0.60)],
        "cough": [("Viral Flu", 0.80), ("Bronchitis", 0.70)]
    }

